// Экран «Покупки»: сначала то, что нужно раньше (day),
// при одном дне — более дешёвое (price).
struct Purchase {
    let name: String
    let day: Int
    let price: Int
}
func shoppingOrder(_ list: [Purchase]) -> [Purchase] {
    list.sorted { a, b in
        if a.day != b.day { return a.day < b.day }
        return a.price < b.price
    }
}

Сначала сравнивается главный признак — день; только при равных днях решает цена. Оба сравнения строгие (`<`), поэтому для двух одинаковых покупок правило вернёт `false` в обе стороны. Можно и кортежем: `(a.day, a.price) < (b.day, b.price)`.

