// TodoItem — из урока
func byDay(_ input: [TodoItem]) -> [TodoItem] {
    var items = input
    for i in 0..<items.count {
        for j in 0..<items.count - 1 - i {
            if items[j].day > items[j + 1].day {
                items.swapAt(j, j + 1)
            }
        }
    }
    return items
}

key:
func byDay(_ input: [TodoItem]) -> [TodoItem] {
    input.sorted { $0.day < $1.day }
}

Двойной цикл — сортировка пузырьком: O(n²) и место для ошибки в границах. `sorted(by:)` делает то же за O(n log n) одной строкой, не трогает входной массив и не требует `var`.

