key:
struct Player {
    let name: String
    let score: Int
}
func leaderboard(_ input: [Player]) -> [Player] {
    var a = input
    for i in a.indices.dropFirst() {
        var j = i
        while j > 0 && a[j - 1].score < a[j].score {
            a.swapAt(j - 1, j)
            j -= 1
        }
    }
    return a
}
let top = leaderboard([
    Player(name: "Аня", score: 40),
    Player(name: "Боря", score: 90),
    Player(name: "Вика", score: 70)
])
print(top.map(\.name))

["Боря", "Вика", "Аня"]. Та же схема вставками, но сравниваем `score` и в обратную сторону: элемент сдвигается влево, пока слева стоит игрок с меньшим счётом. `dropFirst()` защищает пустой массив, где `1..<a.count` упал бы.

