// TodoItem — из урока. По памяти:
// 1) weekOrder(_:) возвращает новый массив: по дню, при равном
//    дне — по названию;
// 2) arrange(_:) переставляет переданный массив на месте по тому
//    же правилу;
// 3) insertionSorted(_:) для [Int] без sorted/sort.

key:
func weekOrder(_ items: [TodoItem]) -> [TodoItem] {
    items.sorted { ($0.day, $0.title) < ($1.day, $1.title) }
}
func arrange(_ items: inout [TodoItem]) {
    items.sort { ($0.day, $0.title) < ($1.day, $1.title) }
}
func insertionSorted(_ input: [Int]) -> [Int] {
    var a = input
    for i in a.indices.dropFirst() {
        var j = i
        while j > 0 && a[j - 1] > a[j] {
            a.swapAt(j - 1, j)
            j -= 1
        }
    }
    return a
}

`weekOrder` не трогает вход и возвращает новый массив, `arrange` меняет массив вызывающего через `inout` и `sort`. Правило строгое и составное. Сортировка вставками сдвигает элемент влево, пока слева больший.
